  localparam BUFFER_DEPTH = 16;
  localparam ADDR_WIDTH = 4;

  // Buffer storage
  reg [7:0] buffer [0:15];

  // Read and write pointers
  reg [3:0] wr_ptr;
  reg [3:0] rd_ptr;

  // Buffer empty and full flags
  reg buffer_empty;
  reg buffer_full;

  // Internal signal for data availability
  reg data_available;

  // Clock edge detection for read/write operations
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wr_ptr <= 4'd0;
      rd_ptr <= 4'd0;
      buffer_empty <= 1'b1;
      buffer_full <= 1'b0;
      data_available <= 1'b0;
    end else begin
      // Update write pointer and buffer state on write
      if (in_data !== 8'h0) begin
        buffer[wr_ptr] <= in_data;
        wr_ptr <= wr_ptr + 1;
        buffer_empty <= 1'b0;
        buffer_full <= (wr_ptr == rd_ptr - 1);
        data_available <= 1'b1;
      end

      // Update read pointer and buffer state on read
      if (data_available && !buffer_empty) begin
        rd_ptr <= rd_ptr + 1;
        buffer_full <= 1'b0;
        buffer_empty <= (rd_ptr == wr_ptr - 1);
        data_available <= 1'b0;
      end
    end
  end

  // Output assignment
  assign out_data = buffer[rd_ptr];

endmodule

